/// The user's home directory on desktop (for user-level skill roots like
/// `~/.claude/skills`, `~/.copilot/skills`); null on mobile/web where those
/// directories do not exist.
///
/// gh-1276 review: the CLI's `homeDirectory()` (`cli_config.dart`) falls
/// back to `USERPROFILE` on Windows where `HOME` is typically unset — the
/// app mirrors that fallback (and `bin/fah.dart`'s `HOME ?? USERPROFILE`
/// order elsewhere) so the desktop app and the CLI share one user store
/// instead of two disjoint ones. [environment] is injectable for tests.
String? desktopHomeDir([Map<String, String>? environment]) {
  if (kIsWeb || Platform.isAndroid || Platform.isIOS) return null;
  final env = environment ?? Platform.environment;
  if (Platform.isWindows) return env['USERPROFILE'] ?? env['HOME'];
  return env['HOME'] ?? env['USERPROFILE'];
}
