+      modelId: 'test-model',
+      baseUrl: 'https://example.test',
+      apiKey: '[REDACTED:Sensitive Value]',
+    ),
+    env: env,
+    streamFunction: _singleTextResponse('ok'),
+    configHomeDir: configHomeDir,
+  );
+  addTearDown(service.dispose);
+  return service;
+}
